@module chrome  src=chrome.lua  loc=1189  mode=chunk  self=chrome
@deps cm, ctx, lib

# Shapes
  @shape  chrome = { colour(name, scope?)->u32, pushChromeStyles(), popChromeStyles(), pushChromeWindow(), popChromeWindow(), verticalSeparator(colour?), disabledIf(cond,fn), row(h?,fn), checkbox(label,v), radio(label,active), headingLabel(text, dimBy?), dimText(alpha)->u32, screenPainter()->painter}  @ 3
  @shape  chrome (pickers) = { makeToolbar()->fn(segments), drawPicker(d), libPicker(d)->items, pickerIsActive()->bool, resetPickerActive(), requestPickerOpen(kind) }  @ 4
  @shape  chrome (status bar) = { makeStatusBar()->fn(segments), statusRects()->{id->rect}, statusEditActive()->bool }  @ 5
  @shape  libPickerSpec = { key: string, current?: any, excludeOthers?: {name->true}, off?: bool = true }  @ 6
  @shape  chrome (shared row primitives) = { rowSelectable(label,sel,flags?)->clicked, treeRow(opts)->{toggled,selected,doubleClicked}, numberStepper(id,value,opts)->changed,value }  @ 7
  @shape  pickerSpec = { kind: string, heading: string?, buttonLabel: string, items: [{label, key, group?, groupLabel?: string, current?=bool, tier?='project'|'global'}], groups?: [{key, label?}], onPick: fn(key, tier), onCancel?: fn(), onCreate?: fn(text, group), onDelete?: fn(key, tier), placement?: 'above', width?, minWidth?, maxWidth?, flat?: bool }  @ 8
  @shape  palettePaneSpec = { x, y, h, label | {tabs=[{key,label}], activeTab, onTab}, draw = fn(childFocused) }  @ 9
  @shape  toolbarSegment = { id: string, heading?: string (presence = collapsible), render: fn, visible?: fn() -> bool, pickers?: [kind] }  @ 311
  @shape  statusSegment = { id: string, label?: string, width: px (the value box; the label sits to its left; omitted by a flags cell, which measures its own), get: fn() -> value, format?: string | fn(v) -> string, visible?: fn() -> bool, edit?: numberEdit | pickEdit | flagsEdit — presence makes the cell a control, set?: fn(v) — the writer for number and pick }  @ 459
  @shape  numberEdit = { kind = 'number', min?, max?, step? = 1 | 'x2' (halve/double), format? }  @ 460
  @shape  pickEdit = { kind = 'pick', items: fn() -> pickerItems }  @ 461
  @shape  flagsEdit = { kind = 'flags', items: [{ label: string, get: fn() -> bool, set: fn(bool) }] — each flag carries its own pair, so the cell needs no get/set }  @ 462

